// План specs/payments-portal.md 2.1 / 2.2 (#5e4fe6). Pre-Prod, preprod-ttp (TTP Test Locks), EN. Только чтение (@prod-safe).
// Решение пользователя 12.11: возвращённые (Refunded) платежи не входят в Total Amount / Total Payments портала и отчёта.
// Факты 17.11: Reports 7 платежей / $150, Portal 6 / $149, под суммой «Refunds not included: $3 (2)».
// 2.1 — Portal: Total Transactions = число строк не-Refunded, Total Amount = их сумма, под суммой «Refunds not included: $X (N)».
// 2.2 — Reports → Payments (This month): отчёт включает все платежи из работ (карта, наличные…), поэтому его итоги ≥ итогов портала;
//       Refunded в них не считаются (проверка: итог отчёта не больше портала + сумма платежей без карты — здесь только нижняя граница).
// Не сверено с сайтом при записи: адрес отчёта (клик Reports → Payments), подписи KPI отчёта по скриншоту 5e4fe6-v2-report-payments-desktop.png.
import { test, expect } from '../../fixtures';
import { ROLE, kpi, openPortal, parseMoney, pp, txRows } from './portal-helpers';

test.describe('Payments totals exclude refunds (#5e4fe6)', () => {
  test('Portal: Total Transactions / Total Amount count only non-refunded rows; "Refunds not included" note is shown #5e4fe6 @desktop @prod-safe', async ({ asUser }) => {
    const page = await asUser(ROLE);
    await openPortal(page);

    const rows = txRows(page);
    const count = await rows.count();
    let sum = 0;
    let live = 0;
    for (let i = 0; i < count; i++) {
      const text = await rows.nth(i).innerText();
      if (/Refunded/.test(text)) continue;
      const amount = text.match(/\$[\d,]+(?:\.\d\d)?/);
      if (amount) { sum += parseMoney(amount[0]); live++; }
    }
    expect(live, 'есть не возвращённые платежи').toBeGreaterThan(0);
    expect(await kpi(page, 'Total Transactions'), 'Total Transactions без Refunded').toBe(String(live));
    expect(parseMoney(await kpi(page, 'Total Amount')), 'Total Amount без Refunded').toBeCloseTo(sum, 2);
    await expect(page.getByText(/Refunds not included:\s*\$[\d,.]+\s*\(\d+\)/)).toBeVisible();
  });

  test('Reports → Payments (This month): Total Payments / Total Amount are not lower than the portal totals #5e4fe6 @desktop @prod-safe', async ({ asUser }) => {
    const page = await asUser(ROLE);
    await openPortal(page);
    const portalCount = Number(await kpi(page, 'Total Transactions'));
    const portalAmount = parseMoney(await kpi(page, 'Total Amount'));

    await page.goto(pp('/Reports'));
    await page.getByText('Payments', { exact: true }).filter({ visible: true }).filter({ hasNotText: 'Payment Portal' }).last().click();
    await expect(page.getByText('Payments Report')).toBeVisible({ timeout: 30_000 });
    await expect(page.getByText('This month').first()).toBeVisible();

    expect(Number(await kpi(page, 'Total Payments')), 'в отчёте платежей не меньше, чем в портале').toBeGreaterThanOrEqual(portalCount);
    expect(parseMoney(await kpi(page, 'Total Amount')), 'сумма отчёта не меньше суммы портала').toBeGreaterThanOrEqual(portalAmount);
  });
});
